



export async function GetNotes(){

      const jsonNotes = await fetch(`${process.env.BASE_URL}/apiTest/api`);
  
      return await jsonNotes.json();
}


export async function PostNotes(noteText:string){
     console.log("PostNotes")
    await fetch(`/apiTest/api`,{method:'POST',body:JSON.stringify(noteText)}) 
}